INSERT INTO `home_crew` VALUES (1,'🎩','蒙奇·D·路飞','草帽小子','船长','草帽一伙','东海·风车村','橡胶果实（人人果实·幻兽种·尼卡）','',3000000000,'草帽海贼团船长，梦想成为海贼王。出生于东海风车村，自幼吃下橡胶果实（实为动物系·人人果实·幻兽种·尼卡形态），被红发香克斯寄托草帽。他单纯、热血、重情义，坚信伙伴高于一切，是能把所有人心凝聚起来的\"天生的领袖\"。在司法岛当众烧毁世界政府旗帜、在顶上战争为救艾斯孤身闯海军本部、在和之国觉醒尼卡形态以太阳神姿态击败凯多，一步步从东海小海贼成长为被称作\"第五位海上皇帝\"的男人。','击败东海恶徒、阿拉巴斯坦打飞克洛克达尔、司法岛救回罗宾、顶上战争失去哥哥艾斯后两年修行，觉醒尼卡形态一拳击落四皇凯多，被世人称为「第五皇」，朝着海贼王梦想全速前进。',1),(2,'🗡️','罗罗诺亚·索隆','海贼猎人','剑士','草帽一伙','东海·霜月村','无','',1111000000,'草帽一伙剑士，梦想成为世界第一大剑豪。出生于东海霜月村，幼年挚友古伊娜意外离世后立下誓言，练成三刀流。他冷静坚毅、意志如铁，是路飞第一个伙伴，也是草帽团的战斗核心。在恐怖三桅帆船篇为保护伙伴承受路飞全部的伤痛，在司法岛、德雷斯罗萨、和之国屡次以惊人剑术击溃强敌，最终目标是超越\"鹰眼\"米霍克。','立下「绝不再败」誓言，司法岛以「三千大千世界」苦战，和之国获得阎魔并砍伤四皇凯多，以成为世界第一大剑豪为目标一路变强。',2),(3,'🍊','娜美','小贼猫','航海士','草帽一伙','东海·可可亚西村','无','',366000000,'草帽一伙航海士，梦想画出全世界的海图。出生于东海可可亚西村，幼年被鱼人阿龙胁迫，被迫绘制海图，后被路飞拯救。她精明、爱财、强悍，是掌控整艘船航行的大脑，擅长气象学，能感知天候变化。在和之国大战中使出雷云宙斯与天候术，实力早已今非昔比。','从阿龙海贼团手中拯救可可亚西村，绘制世界海图的梦想从未改变，草帽团的航海士兼财务总管，一次次在风浪中指引航线。',3),(4,'🎯','乌索普','GOD','狙击手','草帽一伙','东海·西罗布村','无','',500000000,'草帽一伙狙击手，自称\"海上勇士\"。出生于东海西罗布村，父亲是红发海贼团的耶稣布。他胆小却勇敢，在最关键的时刻从不退缩，名言是\"狙击手，就是要在别人看不见的地方保护伙伴\"。在德雷斯罗萨以超远距离狙杀砂糖、成为解放玩具士兵的关键，被称作\"GOD乌索普\"。','从爱说谎的胆小鬼成长为「大神乌索普」，德雷斯罗萨以见闻色霸气封神「GOD」，始终践行「勇敢的海上战士」的誓言。',4),(5,'🚬','文斯莫克·山治','黑脚','厨师','草帽一伙','北海·杰尔马王国','无','',1032000000,'草帽一伙厨师，梦想找到传说之海\"ALL BLUE\"。出生于北海杰尔马王国的文斯莫克家族，自幼被家族虐待，后逃出师从红脚哲普。他尊重食物与女性，绝不浪费粮食，是船上无与伦比的厨师兼战斗员。在蛋糕岛篇与家族和解、在鬼岛大战中以\"魔神风脚\"击碎百兽凯多麾下强敌，黑脚山治的名号响彻新世界。','坚守骑士道与厨师之魂，蛋糕岛篇为伙伴与家族两难抉择，觉醒杰尔马血统因子，梦想找到传说中的 All Blue。',5),(6,'🦌','托尼托尼·乔巴','爱之勇者','船医','草帽一伙','伟大航路·磁鼓王国','人人果实','',1000,'草帽一伙船医，一只吃下人人果实的驯鹿。出生于伟大航路磁鼓王国，被养父希鲁鲁克医生救下，继承了\"万能药\"的信念。他天真善良、医术高超，能变身多种形态，梦想成为能治愈一切疾病的医生。虽然悬赏金只有1000贝利，却是草帽团不可或缺的伙伴与团宠。','人人果实能力者，磁鼓岛为救希鲁鲁克医娘传承医术，是草帽团最可爱的船医，梦想成为能治愈一切疾病的万能药。',6),(7,'📚','妮可·罗宾','恶魔之子','考古学家','草帽一伙','西海·奥哈拉','花花果实','',930000000,'草帽一伙考古学家，梦想解读历史正文、寻找空白的一百年真相。出生于西海奥哈拉，8岁时奥哈拉被屠魔令毁灭，成为\"恶魔之子\"被世界政府通缉。她冷静聪慧、腹黑幽默，吃下花花果实，可在任意地方长出身体部位。在司法岛那句\"说我想活下去\"震撼人心，最终成为能读懂历史正文的关键人物。','奥哈拉唯一幸存者，能解读历史正文的考古学家，司法岛被路飞喊出「说你想活下去」后真心融入草帽团，探寻空白一百年的真相。',7),(8,'🔧','弗兰奇','铁人','船匠','草帽一伙','南海（出生）','无（改造人）','',394000000,'草帽一伙船匠，梦想让\"桑尼号\"环绕世界一周。出生于南海，被海贼父母遗弃，师从鱼人汤姆，继承其造船技艺。他是改造人，身体藏有可乐驱动的武器系统，性格奔放热情，动手能力极强。在鬼岛大战中击碎杰尔马科技战舰，是草帽团最可靠的机械战力。','天才船匠，用可乐驱动身体，为草帽团打造了桑尼号，和之国驾驶弗兰奇将军大放异彩，梦想乘着自己的船航行到世界尽头。',8),(9,'🎻','布鲁克','灵魂之王','音乐家','草帽一伙','西海','黄泉果实','',383000000,'草帽一伙音乐家，一个活了90多年的骷髅。出生于西海，吃下黄泉果实，死后灵魂回到骷髅复活。他乐观幽默、绅士礼貌，梦想是与拉布重逢。作为音乐家能演奏小提琴、能御剑，还能以灵魂能力攻击敌人，是草帽团里最年长也最快乐的一员。','黄泉果实能力者，五十年前与鲸鱼拉布的约定贯穿一生，一曲《宾克斯的美酒》连接两代人的思念，是草帽团的音乐家。',9),(10,'👊','甚平','海侠','舵手','草帽一伙','伟大航路·鱼人岛','无','',1100000000,'草帽一伙舵手，原王下七武海、太阳海贼团舵手。出生于鱼人岛，是鲸鲨鱼人，侠肝义胆、稳重可靠，被称为\"海侠\"。他坚守鱼人的尊严与对艾斯的兄弟情，在鬼岛大战中以\"鱼人空手道\"击退凯多，正式加入草帽一伙，成为船上的舵手与定海神针。','前七武海「海侠」，推进城与顶上战争多次救路飞于危难，鱼人岛篇正式加入草帽团，梦想人类与鱼人族和平共处。',10),(11,'🔴','香克斯','红发','船长','红发海贼团','西海','无','',4048900000,'红发海贼团船长，四皇之一。出生于西海，曾是海贼王罗杰船上见习船员，后自立门户。他是路飞成为海贼的引路人，将草帽托付给路飞并约定在顶点重逢。他实力深不可测，霸气无人能敌，能用\"面子\"震慑海军与四皇，是当前大海上最神秘的强者之一。','四皇「红发」，把草帽与梦想托付给路飞的引路人，顶上战争一出现便终结了战斗，是海贼世界举足轻重的传奇海贼。',11),(12,'🏔️','爱德华·纽盖特','白胡子','船长','白胡子海贼团','伟大航路·斯芬克斯','震震果实','',5046000000,'白胡子海贼团船长，被称为\"世界最强的男人\"。出生于伟大航路斯芬克斯，吃下震震果实，能引发海啸与地震。他将所有船员视为儿子，一生只求一个家。顶上战争中为救艾斯孤身战海军本部，身中267处刀伤、152发子弹仍屹立不倒，最终以\"我是旧时代的残党\"悲壮谢幕。','四皇「白胡子」，震震果实威震世界，顶上战争为救艾斯战死，临终喊出「ONE PIECE 是真实存在的」，再次引爆大海贼时代。',12),(13,'🌑','马歇尔·D·蒂奇','黑胡子','船长','黑胡子海贼团','伟大航路·暗暗岛','暗暗果实＋震震果实','',3996000000,'黑胡子海贼团提督，四皇之一，史上唯一拥有两颗恶魔果实的人（暗暗果实+震震果实）。出生于伟大航路，隐忍二十年等待时机，野心勃勃、不择手段。他杀害了第四队队长萨奇夺取暗暗果实，抓住艾斯献给海军、引发顶上战争，最终夺取白胡子震震果实，一步步登上四皇宝座。','四皇「黑胡子」，唯一同时拥有暗暗果实与震震果实的男人，野心勃勃、阴险狡诈，是路飞宿命中的最大对手之一。',13),(14,'🐉','凯多','百兽','总督','百兽海贼团','新世界·和之国','鱼鱼果实·幻兽种·青龙','',4611100000,'百兽海贼团总督，四皇之一，被称为\"最强生物\"。出生于新世界和之国，吃下鱼鱼果实·幻兽种·青龙形态，能化为巨龙呼风唤雨。他崇尚\"战争才是世界的规则\"，企图建立全动物系军团发动世界战争。在和之国大战中被路飞以觉醒尼卡形态击落，其海贼团随之瓦解。','四皇「百兽」，鱼鱼果实·青龙形态，和之国被路飞的尼卡形态一拳击落，统治和之国多年的暴君就此落幕。',14),(15,'🎂','夏洛特·玲玲','BIG MOM','船长','BIG MOM 海贼团','新世界·万国','魂魂果实','',4388000000,'BIG MOM海贼团船长，四皇之一。出生于新世界万国，吃下魂魂果实，能操纵灵魂、赋予万物生命。她暴虐任性、贪食甜点，渴望建立所有种族和平共处的\"万国\"，但手段残忍。在与基德、罗的联手作战中被击败，退出了四皇之位。','四皇「BIG MOM」，魂魂果实能力者，万国的统治者，蛋糕岛篇与草帽团激战，是令人生畏的女海贼皇帝。',15),(16,'♥️','特拉法尔加·罗','死亡外科医生','船长','心脏海贼团','北海·弗雷凡斯','手术果实','',3000000000,'心脏海贼团船长，\"极恶世代\"十一超新星之一。出生于北海弗雷凡斯，幼年家乡因铂铅病被毁灭，怀抱着对多弗朗明哥的仇恨。吃下手术果实，能创造\"ROOM\"空间进行任意切割与交换，是价值50亿贝利的\"究极恶魔果实\"。在与凯多之战中与基德联手击落BIG MOM，是新时代的代表之一。','心脏海贼团船长，手术果实能力者，与路飞结盟对抗四皇，和之国联手击败大妈，是头脑与实力兼备的谋略家。',16),(17,'🧲','尤斯塔斯·基德','船长','船长','基德海贼团','南海','磁磁果实','',3000000000,'基德海贼团船长，\"极恶世代\"十一超新星之一，与路飞、罗齐名。出生于南海，吃下磁磁果实，能操纵金属。他桀骜不驯、残暴好斗，却也重情义。在万国篇被凯多击败后越狱，与罗联手在和之国击落BIG MOM，成为推翻旧时代的重要战力。','基德海贼团船长，磁磁果实能力者，和之国与路飞、罗联手击败双皇，脾气火爆但重情重义。',17),(18,'🌋','萨卡斯基','赤犬','海军元帅','海军本部','北海','岩浆果实','',0,'海军本部元帅，代号\"赤犬\"。出生于北海，吃下岩浆果实，能化为岩浆攻击，破坏力堪称海军之最。他信奉\"绝对的正义\"，手段极端狠辣，顶上战争中亲手击杀艾斯、重创路飞。在与青雉的十天大战中获胜升任元帅，是路飞等人的宿敌。','海军元帅「赤犬」，岩浆果实能力者，顶上战争击杀艾斯的元凶，坚持「绝对的正义」的强硬派代表。',18),(19,'🧊','库赞','青雉','原海军大将','海军（已退役）','南海','冰冻果实','',0,'原海军大将，代号\"青雉\"。出生于南海，吃下冰冻果实，能冻结万物。他信奉\"懒散的正义\"，性格慵懒却洞察世事。在与赤犬争夺元帅之位的十天大战中败北，断腿后离开海军，成为自由人，暗中观察着世界的走向。','原海军大将「青雉」，冰冻果实能力者，与赤犬争夺元帅失败后退役，坚持懒散的正义。',19),(20,'🟡','波鲁萨利诺','黄猿','海军大将','海军本部','北海','闪光果实','',0,'海军本部大将，代号\"黄猿\"。出生于北海，吃下闪光果实，能以光速移动、发射激光。他总是一副漫不经心的懒散模样，实力却深不可测，信奉\"模糊的正义\"。作为海军最高战力之一，多次与海贼强者交锋，其真正立场始终成谜。','海军大将「黄猿」，闪光果实能力者，实力深不可测，常常一副游刃有余的样子。',20),(21,'👊','蒙奇·D·卡普','铁拳','海军中将','海军本部','东海·风车村','无','',0,'海军本部中将，被称为\"铁拳卡普\"，是路飞的爷爷、龙的父亲。他追击海贼王罗杰多年，曾多次将其逼入绝境，是海军中唯一能被称为\"英雄\"的人。他不使用恶魔果实，凭一双铁拳和霸王色霸气纵横大海，顶上战争时虽身居海军却放水救下路飞，是集正义与亲情于一身的老兵。','海军英雄「铁拳」，路飞的爷爷，曾与罗杰多次交锋的传奇中将，实力不逊大将。',21),(22,'🦸','克比','英雄','海军少将（SWORD）','海军本部','东海','无','',0,'海军本部少将，SWORD机密行动部队成员。出生于东海，是路飞、艾斯少年时代的伙伴，一路追随着路飞的脚步成长。他善良正直，从懦弱少年蜕变为独当一面的海军军官，梦想是成为海军大将。在蛋头岛篇加入SWORD，与路飞并肩作战对抗世界政府。','从胆小少年成长为 SWORD 少将，路飞最早的伙伴之一，一路追寻梦想的海军新星。',22),(23,'🚭','斯摩格','白猎人','海军中将','海军本部','伟大航路·罗格镇','烟雾果实','',0,'海军本部中将，代号\"白猎人\"。出生于伟大航路罗格镇，吃下烟雾果实，能化为烟雾战斗。他固执坚持自己的正义，在罗格镇曾差点抓住路飞，此后一路追击草帽团。他并非冷酷无情，对海贼也有自己的判断，是海军中难得的良知派。','海军中将「白猎人」，烟雾果实能力者，从罗格镇起一路追捕路飞，坚守自己的正义。',23),(24,'👁️','乔拉可尔·米霍克','鹰眼','王下七武海','无','伟大航路·克拉伊咖那岛','无','',3590000000,'王下七武海，被称为\"鹰眼\"，是世界第一大剑豪。出生于伟大航路克拉伊咖那岛，不使用恶魔果实，凭一把黑刀\"夜\"纵横大海，是索隆超越的目标。他孤高冷峻、深不可测，曾与红发香克斯多次交锋，是海上真正的剑术顶点。','世界第一大剑豪「鹰眼」，索隆的目标与师父，原七武海，实力深不可测的孤高剑士。',24),(25,'☠️','哥尔·D·罗杰','海贼王','罗杰海贼团船长','罗杰海贼团','东海·罗格镇','无','',5506480000,'史上第一位完成伟大航路、征