--

LOCK TABLES `home_route` WRITE;
/*!40000 ALTER TABLE `home_route` DISABLE KEYS */;
INSERT INTO `home_route` VALUES (1,'🌊','东海启程线','东海',1,'路飞从风车村出海的第一段旅程，途径谢尔兹镇、橘子镇，击败斧手摩根、小丑巴基，收下索隆、娜美、乌索普、山治等最初的伙伴，是一切冒险的起点。',1),(2,'🏝️','伟大航路前半','伟大航路',3,'进入伟大航路的入口，穿过双子岬、威士忌山峰，遇到鲸鱼拉布、与克比重逢，草帽团在这里正式踏上寻找海贼王之路，并立下各自的梦想誓言。',2),(3,'🏜️','阿拉巴斯坦线','伟大航路',4,'草帽团登陆沙漠王国阿拉巴斯坦，与克洛克达尔的巴洛克工作社正面交锋，路飞首次击败王下七武海，拯救了薇薇公主与整个国家，也让草帽团声名大噪。',3),(4,'⚙️','水之都环岛线','伟大航路',3,'环绕水之都的海上路线，草帽团在这里与CP9对决、失去梅利号，罗宾被抓走，路飞开发出二档、三档，是草帽团最惨痛也最成长的一段旅程。',4),(5,'👹','和之国航线','新世界',5,'通往和之国的危险航线，沿途被凯多的百兽海贼团与和之国武士严密把守，是四皇凯多的地盘，也是路飞觉醒尼卡形态、击落凯多的决战之地。',5),(6,'❄️','磁鼓王国线','伟大航路',2,'通往磁鼓王国的航线，草帽团在这里遇到船医乔巴，路飞背着重伤的娜美登上磁鼓山求医，乔巴加入，是草帽团收获\"万能药\"伙伴的地方。',6),(7,'⛅','空岛航线','伟大航路',4,'通往空岛的天路航线，借助上升海流冲上万米高空，路飞在这里与神·艾尼路对决，为拉夫坦路的历史正文埋下伏笔，也是山治第一次展露厨艺之魂。',5),(8,'🐟','鱼人岛航线','新世界',4,'深入海底一万米的鱼人岛航线，草帽团在这里与霍迪·琼斯对决，路飞展现霸王色霸气，甚平正式与草帽团结缘，也为鱼人与人类的和平埋下希望。',7),(9,'🎭','德雷斯罗萨线','新世界',5,'通往德雷斯罗萨的航线，路飞在这里与多弗朗明哥决战，开启四档\"弹力人\"，乌索普觉醒见闻色霸气成为\"GOD\"，拯救了整个被玩具化的国家。',8),(10,'🐘','佐乌岛线','新世界',4,'通往象背之岛佐乌的航线，草帽团在这里得知了历史正文、光月一族与和之国的秘密，路飞与毛皮族缔结同盟，为和之国决战集结力量。',9),(11,'🍰','蛋糕岛航线','新世界',5,'通往BIG MOM领地蛋糕岛的航线，山治为救家人深陷其中，路飞与卡塔库栗史诗级对决，草帽团大闹茶会，最终救回山治并全身而退。',10),(12,'🤖','蛋头岛航线','新世界',5,'通往最终章蛋头岛的航线，草帽团登陆天才贝加庞克的科学之岛，与海军大将绿牛、赤犬的正面对抗，最终章的大幕在这里缓缓拉开。',11),(13,'🏁','拉夫坦路','伟大航路终点',5,'伟大航路的终点，海贼王罗杰留下ONE PIECE的传说之岛。只有集齐四块红色历史正文、破解其坐标的人才能抵达，是无数海贼梦寐以求的终点。',12);
/*!40000 ALTER TABLE `home_route` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `home_shop`
