LOCK TABLES `home_shop` WRITE;
/*!40000 ALTER TABLE `home_shop` DISABLE KEYS */;
INSERT INTO `home_shop` VALUES (1,'🍺','风车村老伯酒馆','餐饮','东海·风车村','海贼麦酒',800,'村口的老酒馆，路飞常在这里听甚平与艾斯的故事，也在这里认识了大伙。',1),(2,'🗡️','罗格镇刀剑铺','武器','东海·罗格镇','名刀「雪走」',1000000,'罗格镇是海贼王罗杰的处刑地，也是索隆在此获得名刀的地方。',2),(3,'🧵','谢尔兹镇杂货铺','杂货','东海·谢尔兹镇','手织草绳',500,'小镇的杂货摊，草帽与绳索的来源地，老板娘总是絮叨个不停。',3),(4,'⚓','卡雷拉公司本社','造船','伟大航路·水之都','定制帆船',300000000,'世界第一造船公司，桑尼号由这里的船匠们倾力打造。',4),(5,'🍬','香波地杂货街','杂货','伟大航路·香波地群岛','泡泡工艺饰品',20000,'泡泡文化盛行的小商品街，出岛前最后的补给站。',5),(6,'🍵','绿洲茶馆','餐饮','伟大航路·阿拉巴斯坦','沙漠凉茶',1200,'沙漠绿洲边的茶馆，旅行者在这里交换情报也交换水。',6),(7,'☁️','云上杂货铺','杂货','空岛·神之国','云贝（贝）',3000,'贩卖储存风与音的贝壳，是空岛居民生活的必需品。',7),(8,'🍰','甜点工坊','餐饮','鱼人岛','珊瑚蛋糕',5000,'鱼人岛的点心铺，连人鱼女王也会派人来买。',8),(9,'🧸','玩具之家','玩具','新世界·德雷斯罗萨','机关人偶',15000,'看似温馨的玩具店，其实藏着被变成玩具的人类秘密。',9),(10,'🍜','阎魔荞麦面摊','餐饮','新世界·和之国','热腾腾荞麦面',800,'花之都街边的面摊，一碗热汤面能温暖一整天的疲惫。',10),(11,'🕯️','古董道具铺','古董','魔幻三角地带','布鲁克遗物唱片',30000,'恐怖三桅帆船靠岸处的老铺子，据说夜间会有影子来买东西。',11),(12,'🔮','未来岛研究所商店','杂货','新世界·蛋头岛','自制万能工具',50000,'贝加庞克研究所的贩卖机，什么都卖，包括失败的发明。',12);
/*!40000 ALTER TABLE `home_shop` ENABLE KEYS */;
UNLOCK TABLES;

