LOCK TABLES `home_story` WRITE;
/*!40000 ALTER TABLE `home_story` DISABLE KEYS */;
INSERT INTO `home_story` VALUES (1,'🌊','东海篇','东海','漫画 1-61 话','动画 1-45 集','路飞、索隆、娜美、乌索普、山治','','BV1Q541137VL','橡胶少年路飞出海，接连打败亚尔丽塔与恶龙，先后收下剑士、航海士、狙击手与厨师，草帽一伙雏形初成。','草帽海贼团的起点。少年蒙奇·D·路飞在海贼王罗杰处刑的感召下，立志成为海贼王。在东海风车村，他受红发香克斯影响，吃下橡胶果实，并与香克斯立下「归还草帽」的约定。十年后，17岁的路飞独自出海，先后在谢尔兹镇救下并招募剑士索隆，在橘子镇结识航海士娜美，在西罗布村帮助乌索普夺回故乡并获赠黄金梅利号，在海上餐厅巴拉蒂招募厨师山治，最终在可可西亚村与鱼人恶龙决战、解放娜美的故乡，凑齐最初五名伙伴。在罗格镇——海贼王罗杰出生与处刑之地，路飞遭遇海军上校斯摩格，幸得神秘人（革命家龙）相助脱险。五人以各自的梦想立誓，跨越颠倒山，正式进入伟大航路，传说就此开始。',1),(2,'🏜️','阿拉巴斯坦篇','伟大航路','漫画 155-217 话','动画 92-130 集','路飞、薇薇、克洛克达尔','','BV1NU4y1b7eZ','为帮助公主薇薇，草帽一伙潜入沙漠王国，揭穿王下七武海克洛克达尔的叛乱阴谋，路飞以橡胶果实之力击碎砂之国阴谋。','进入伟大航路后，草帽一伙在双子岬结识等待伙伴的岛屿鲸鱼拉布。为救治生病的娜美，众人登上医疗大国磁鼓岛，在魔女Dr.古蕾娃处结识蓝鼻子驯鹿乔巴，击败前国王瓦波尔，乔巴以船医身份加入。随后他们护送阿拉巴斯坦公主薇薇回国，对抗王下七武海克洛克达尔及其犯罪组织巴洛克工作社。路飞先后两次败给克洛克达尔，最终在沙漠遗迹中以热血之拳将其击倒，揭露「跳舞粉」阴谋，让一场及时雨浇熄内战。战后，原巴洛克工作社副社长妮可·罗宾加入草帽一伙，成为考古学家。薇薇选择留下守护祖国，虽未上船却永远是伙伴。路飞悬赏金升至1亿贝里。',2),(3,'⛅','空岛篇','伟大航路·加雅岛','漫画 237-302 话','动画 144-193 集','路飞、艾尼路、山迪亚战士','','BV12S4y1C7wu','乘上升海流抵达一万米高空，卷入神之国四百年战争，路飞以橡胶之身击败雷神艾尼路，敲响黄金钟。','在加雅岛，路飞被贝拉米嘲笑「空岛只是白日梦」却选择不还手，诠释了对梦想的坚信。在「大骗子」诺兰德后代库力凯的帮助下，草帽一伙乘上升海流抵达万米高空的空岛。空岛由「神」艾尼路统治，他凭借自然系轰雷果实的力量残暴压榨天使族与山迪亚人。路飞因橡胶不导电而天然克制艾尼路，最终敲响黄金钟，让400年前诺兰德的约定得以回应，终止了长达四百年的战争。空岛篇揭示了「历史正文」与古代王国的重要线索，也让路飞展现了「即便神也能战胜」的信念。',3),(4,'⚖️','司法岛篇','伟大航路·水之都','漫画 375-430 话','动画 263-312 集','路飞、罗宾、弗兰奇、CP9','','BV1bB4y1u7gU','为夺回妮可·罗宾，草帽一伙闯入世界政府司法岛，向世界政府宣战并烧毁旗帜，桑尼号由此诞生。','水之都与司法岛篇被誉为尾田笔力的巅峰。黄金梅利号龙骨严重受损，路飞决定换船，与乌索普爆发决裂。罗宾为保护伙伴，被迫接受CP9的胁迫而「背叛」。草帽一伙追至世界政府直辖的司法岛，路飞当众烧毁世界政府旗帜，向世界宣战；罗宾嘶声呐喊「我想活下去」，触动所有人心。最终击败CP9的罗布·路奇，救回罗宾。梅利号在燃烧中告别，万里阳光号成为新船，弗兰奇以船匠身份加入。路飞悬赏达3亿贝里。',4),(5,'💀','恐怖三桅帆船篇','魔幻三角地带','漫画 442-489 话','动画 337-381 集','路飞、布鲁克、月光·莫利亚','','BV1aWnz6QEvj','影子被夺走的恐怖之岛，路飞击败七武海莫利亚，布鲁克加入草帽一伙，甚平与小丑巴基亦在此现身。','进入魔幻三角地带，草帽一伙登上世界最大海贼船「恐怖三桅帆船」，遭遇王下七武海月光·莫利亚。莫利亚用影影果实夺取众人的影子制造僵尸军团，路飞的影子被塞入魔人奥兹体内。路飞吸收大量影子化身「梦魇路飞」重创奥兹。骷髅音乐家布鲁克为完成与鲸鱼拉布的约定，取回影子后正式加入草帽一伙。战后巴索罗米·熊来袭，索隆挺身承担路飞的全部伤痛，展现了无言的忠诚。',5),(6,'🔥','顶上战争篇','海军本部·马林梵多','漫画 550-580 话','动画 459-489 集','白胡子、艾斯、赤犬、黑胡子','','BV1Nw99BFEDg','为营救艾斯，白胡子海贼团与海军本部爆发史上最大战争，艾斯陨落，路飞失去兄长，时代开始剧烈崩塌。','顶上战争是改变世界格局的巅峰之战。路飞为救即将被处刑的哥哥艾斯，闯入海军本部马林梵多。白胡子海贼团倾巢而出，与海军三大将、七武海展开全面战争。路飞历经推进城越狱，带着众海贼抵达战场。艾斯被救出的瞬间，却为保护路飞被赤犬击杀；白胡子也随之战死。黑胡子海贼团趁乱搅局，最终红发香克斯赶到调停。路飞陷入绝望，在雷利的引导下决定修行两年。这场战争改变了世界势力版图，也开启了新时代。',6),(7,'🐟','鱼人岛篇','新世界·鱼人岛','漫画 601-653 话','动画 517-574 集','路飞、甚平、白星、霍迪·琼斯','','BV1GxZpYqEoY','穿越红土大陆抵达海底乐园，粉碎霍迪·琼斯的政变，揭开白星公主与诺亚方舟的古老誓约。','顶上战争两年后，草帽一伙于香波地群岛重聚，实力大增。他们潜入万米深海，抵达鱼人岛，卷入了新鱼人海贼团霍迪·琼斯对龙宫王国的政变。霍迪等人因继承的仇恨而敌视人类，路飞在甚平与白星公主的帮助下击败霍迪，宣扬「人类与鱼人平等」的理念。鱼人岛篇揭示了古代兵器「波塞冬」的线索，路飞正式向四皇BIG MOM宣战。',7),(8,'🎭','德雷斯罗萨篇','新世界·德雷斯罗萨','漫画 700-801 话','动画 629-746 集','路飞、多弗朗明戈、罗、蕾贝卡','','BV1254y1G7Kz','路飞与罗的结盟之战，揭穿多弗朗明戈的黑暗交易，鸟笼笼罩全岛，最终以四档弹力终结其统治。','进入新世界，路飞与特拉法尔加·罗结成海贼同盟，目标扳倒四皇凯多。他们先攻破庞克哈萨德，抓捕科学家凯撒·库朗，随后向王下七武海多弗朗明哥宣战。在德雷斯罗萨，路飞参加竞技场，与失散的哥哥萨博重逢，萨博继承艾斯的烧烧果实。路飞觉醒四档，击败多弗朗明哥，解放了被玩具化奴役的人民。战后七支海贼团宣誓效忠，草帽大船团正式成立。路飞悬赏达5亿贝里。',8),(9,'🐘','佐乌篇','新世界·佐乌','漫画 802-822 话','动画 751-779 集','毛皮族、光月家族、锦卫门','','BV1z5411T7a7','巨象背上的毛皮族之国，光月家臣在此重聚，众人得知路标历史本文与和之国的秘密。','草帽大船团成立后，众人登上巨象背上的佐乌岛，结识毛皮族与光月桃之助。佐乌岛揭示了两大秘密：一是通往拉夫坦路需要四块「路标历史正文」，二是和之国被凯多统治。此时山治被杰尔马家族与BIG MOM海贼团以联姻相逼，留下一封告别信离去。草帽一伙决定兵分两路，一部分前往蛋糕岛救山治，其余前往和之国准备讨伐凯多。',9),(10,'🍰','蛋糕岛篇','新世界·万国','漫画 823-902 话','动画 783-877 集','山治、路飞、BIG MOM、卡塔库栗','','BV1pJ41137ez','为带回山治，草帽一伙闯入 BIG MOM 的茶会，在镜世界展开激战，山治以最温柔的踢技战胜最强将星。','路飞等人潜入四皇BIG MOM的万国，为夺回被逼联姻的山治。山治因杰尔马血统因子的觉醒与对伙伴的愧疚而挣扎，最终向路飞喊出「我想回桑尼号」。路飞与将星卡塔库栗在镜世界展开真男人的决斗，见闻色霸气进化到预见未来，最终险胜。草帽一伙在BIG MOM的疯狂追击下全身而退，路飞悬赏升至15亿贝里，被世人称为「第五位海上皇帝」。',10),(11,'👹','和之国篇','新世界·和之国','漫画 909-1057 话','动画 890-1085 集','路飞、凯多、光月日和、大和','','BV1b64y147RW','讨伐百兽凯多的鬼岛大战，路飞觉醒尼卡形态，二十年的锁国终被打破，和之国迎来黎明。','草帽一伙联合罗、基德、锦卫门等，与光月家的武士、毛皮族、大和等组成联盟，讨伐统治和之国的四皇凯多与黑炭大蛇。鬼岛决战中，路飞觉醒橡胶果实的真正形态「人人果实·幻兽种·尼卡形态」（太阳神），以全新的姿态击败凯多；索隆获阎魔、山治觉醒血统因子。凯多与大妈双双战败，和之国迎来开国。战后路飞、罗、基德被并列为新四皇，世界格局再次剧变。',11),(12,'🤖','蛋头岛篇','新世界·蛋头岛','漫画 1060 话起','动画 1086 集起','路飞、贝加庞克、乔伊波伊、五老星','','BV1Mw4m1k7u5','未来岛上遇见天才科学家贝加庞克，炽天使与机器巨鲨登场，世界政府最高战力五老星亲临，空白的一百年真相揭开。','草帽一伙抵达天才科学家贝加庞克所在的未来岛「蛋头岛」，卷入世界政府对贝加庞克的围剿。CP0、海军大将黄猿、五老星接连来袭。贝加庞克为保护研究成果与真相，向全世界公开了「空白一百年」的秘密后牺牲。路飞与五老星对峙，展现了尼卡形态的威能。蛋头岛篇揭示了One Piece与「母火种」的关联，世界政府的最高机密濒临曝光，最终决战一触即发。',12);
/*!40000 ALTER TABLE `home_story` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `home_wanted`
--

DROP TABLE IF EXISTS `home_wanted`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `home_wanted` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `icon` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '?‍☠️' COMMENT '卡片图标(emoji)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '海贼名',
  `epithet` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '称号',
  `crew` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '所属海贼团',
  `bounty` bigint NOT NULL DEFAULT '0' COMMENT '悬赏金额（贝利）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '悬赏理由/罪行描述',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_wanted_name` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='悬赏令';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `home_wanted`
--

LOCK TABLES `home_wanted` WRITE;
/*!40000 ALTER TABLE `home_wanted` DISABLE KEYS */;
INSERT INTO `home_wanted` VALUES (1,'🎩','蒙奇·D·路飞','草帽小子','草帽一伙',3000000000,'多次公然对抗世界政府，火烧司法岛旗帜，闯入海军本部，觉醒太阳神尼卡形态，被认定为\"世界最凶恶罪犯\"级别的威胁。'),(2,'🗡️','罗罗诺亚·索隆','海贼猎人','草帽一伙',1111000000,'海贼猎人出身，三刀流剑士，屡次击溃海军与七武海，目标直指世界第一大剑豪，悬赏金随其剑术不断攀升。'),(3,'🍊','娜美','小贼猫','草帽一伙',366000000,'草帽团航海士，盗窃多起、操纵天候作战，虽悬赏金不高，却是掌控整艘船航行的关键人物。'),(4,'🎯','乌索普','GOD','草帽一伙',500000000,'德雷斯罗萨之战中以超远距离狙杀砂糖、解放玩具士兵，被误认为\"神\"，悬赏金因\"GOD\"之名暴涨。'),(5,'🚬','文斯莫克·山治','黑脚','草帽一伙',1032000000,'文斯莫克家族第三子，草帽团厨师，屡次踢飞海军强者，黑脚山治之名令海军头痛。'),(6,'🦌','托尼托尼·乔巴','爱之勇者','草帽一伙',1000,'草帽团船医，人人果实能力者，虽被严重低估悬赏仅1000贝利，却是能治愈一切疾病的医生。'),(7,'📚','妮可·罗宾','恶魔之子','草帽一伙',930000000,'\"恶魔之子\"，能解读历史正文的考古学家，世界政府最想抹杀的存在之一，悬赏金随其重要性持续攀升。'),(8,'🔧','弗兰奇','铁人','草帽一伙',394000000,'改造人船匠，桑尼号的制造者，多次击碎海军战舰，是草帽团最可靠的机械战力。'),(9,'🎻','布鲁克','灵魂之王','草帽一伙',383000000,'黄泉果实能力者，骷髅音乐家，灵魂之王，虽已\"死\"却仍活跃在海上，是草帽团最年长的成员。'),(10,'☁️','唐吉诃德·多弗朗明戈','天夜叉','唐吉诃德家族',340000000,'唐吉诃德家族首领，线线果实能力者，原德雷斯罗萨国王，被路飞四档击溃。'),(11,'👊','甚平','海侠','草帽一伙',1100000000,'原王下七武海，太阳海贼团舵手，鱼人空手道大师，正式加入草帽团后成为舵手。'),(12,'🔴','香克斯','红发','红发海贼团',4048900000,'四皇之一，红发海贼团船长，路飞的引路人，拥有震慑海军的\"面子\"与无人能敌的霸气。'),(13,'🏔️','爱德华·纽盖特','白胡子','白胡子海贼团',5046000000,'\"世界最强的男人\"，震震果实能力者，白胡子海贼团船长，顶上战争中为救艾斯孤身战海军本部。'),(14,'🌑','马歇尔·D·蒂奇','黑胡子','黑胡子海贼团',3996000000,'黑胡子海贼团提督，史上唯一双果实能力者，夺取白胡子震震果实，野心勃勃的四皇。'),(15,'🐉','凯多','百兽','百兽海贼团',4611100000,'百兽海贼团总督，鱼鱼果实·青龙形态，\"最强生物\"，企图发动世界战争，被路飞觉醒尼卡形态击落。'),(16,'🎂','夏洛特·玲玲','BIG MOM','BIG MOM 海贼团',4388000000,'BIG MOM海贼团船长，魂魂果实能力者，四皇之一，渴望建立万国，被基德与罗联手击落。'),(17,'♥️','特拉法尔加·罗','死亡外科医生','心脏海贼团',3000000000,'心脏海贼团船长，手术果实能力者，极恶世代十一超新星之一，与路飞、基德齐名。'),(18,'🧲','尤斯塔斯·基德','船长','基德海贼团',3000000000,'基德海贼团船长，磁磁果实能力者，极恶世代之一，与罗联手击落BIG MOM。'),(19,'🐊','克洛克达尔','沙漠王','巴洛克工作社',81000000,'巴洛克工作社首领，沙沙果实能力者，曾企图夺取阿拉巴斯坦，被路飞击败。'),(20,'👁️','乔拉可尔·米霍克','鹰眼','无（七武海）',3590000000,'王下七武海，世界第一大剑豪，索隆要超越的目标，孤高的剑术顶点。'),(21,'🤡','巴基','小丑','巴基速递',3189000000,'巴基速递首领，前罗杰海贼团见习船员，虽实力平平却凭运气登上七武海之位。');
/*!40000 ALTER TABLE `home_wanted` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_user`
--

DROP TABLE IF EXISTS `sys_user`;
